from baserequest import BaseRequest

# ============ MT4 ORDER TYPES (Replaces OANDA) ============

class TradeID:
    """Trade ID wrapper"""
    def __init__(self, trade_id):
        self.value = str(trade_id)


class PriceValue:
    """Price value wrapper"""
    def __init__(self, price):
        self.value = str(price)


class TimeInForce:
    """Time in Force"""
    GTC = "GTC"  # Good Till Cancelled
    GTD = "GTD"  # Good Till Date
    GFD = "GFD"  # Good For Day
    IOC = "IOC"  # Immediate or Cancel
    FOK = "FOK"  # Fill or Kill


class OrderType:
    """MT4 Order Types"""
    TAKE_PROFIT = "TAKE_PROFIT"
    LIMIT = "LIMIT"
    MARKET = "MARKET"
    STOP = "STOP"
    STOP_LIMIT = "STOP_LIMIT"


class TakeProfitOrderRequest(BaseRequest):
    """create a TakeProfit OrderRequest.

    TakeProfitOrderRequest is used to build the body for a TakeProfitOrder.
    The body can be used to pass to the OrderCreate endpoint.
    
    NOTE: This has been adapted from OANDA to support MT4 order structure.
    For MT4, take profit orders are handled via the MT4 client directly.
    This class now serves as a data structure for order parameters.
    """

    def __init__(self,
                 tradeID,
                 price,
                 clientTradeID=None,
                 timeInForce=TimeInForce.GTC,
                 gtdTime=None,
                 clientExtensions=None):
        """
        Instantiate a TakeProfitOrderRequest.

        Parameters
        ----------

        tradeID : string (required)
            the tradeID of an existing trade

        price: float (required)
            the price indicating the target price to close the order.

        Example
        -------

        >>> from mt4_take_profit_request import TakeProfitOrderRequest
        >>> 
        >>> # Create a take profit order request
        >>> order = TakeProfitOrderRequest(
        ...     tradeID="1234",
        ...     price=1.1000
        ... )
        >>> 
        >>> # For actual MT4 execution, use the MT4 client:
        >>> from mt4_price_provider import get_mt4_prices
        >>> mt4 = get_mt4_prices()
        >>> # Modify existing position with take profit
        >>> # mt4.modify_position(tradeID, take_profit=1.1000)
        """
        super(TakeProfitOrderRequest, self).__init__()

        # allowed: GTC/GFD/GTD
        if timeInForce not in [TimeInForce.GTC,
                               TimeInForce.GTD,
                               TimeInForce.GFD]:
            raise ValueError("timeInForce: {}".format(timeInForce))

        # by default for a TAKE_PROFIT order
        self._data.update({"type": OrderType.TAKE_PROFIT})
        self._data.update({"timeInForce": timeInForce})

        # required
        self._data.update({"tradeID": TradeID(tradeID).value})
        self._data.update({"price": PriceValue(price).value})

        # optional, but required if
        self._data.update({"gtdTime": gtdTime})
        if timeInForce == TimeInForce.GTD and not gtdTime:
            raise ValueError("gtdTime missing")

        # optional
        self._data.update({"clientExtensions": clientExtensions})

    @property
    def data(self):
        """data property.

        return the JSON order body
        """
        return dict({"order": super(TakeProfitOrderRequest, self).data})


# ============ MT4 Take Profit Execution Helper ============

class MT4TakeProfitExecutor:
    """
    Helper class to set take profit orders in MT4 (replaces OANDA execution)
    """
    
    def __init__(self):
        from mt4_price_provider import get_mt4_prices
        self.mt4 = get_mt4_prices()
    
    def set_take_profit(self, trade_id, price):
        """
        Set take profit for an existing trade in MT4
        
        Note: MT4 uses ticket numbers (integers) instead of string trade IDs
        """
        try:
            # Convert trade_id to integer (MT4 uses numeric ticket numbers)
            ticket = int(trade_id) if isinstance(trade_id, str) else trade_id
            
            # MT4 modify position with take profit
            # Note: This requires the modify_position method in your MT4 client
            result = self.mt4.modify_position(ticket, take_profit=price)
            return result
        except Exception as e:
            return {'success': False, 'error': str(e)}
    
    def set_stop_loss(self, trade_id, price):
        """
        Set stop loss for an existing trade in MT4
        """
        try:
            ticket = int(trade_id) if isinstance(trade_id, str) else trade_id
            result = self.mt4.modify_position(ticket, stop_loss=price)
            return result
        except Exception as e:
            return {'success': False, 'error': str(e)}


# ============ Stop Loss Order Request (MT4 Equivalent) ============

class StopLossOrderRequest(BaseRequest):
    """Stop Loss Order Request for MT4 (replaces OANDA stop loss orders)"""
    
    def __init__(self,
                 tradeID,
                 price,
                 clientTradeID=None,
                 timeInForce=TimeInForce.GTC,
                 gtdTime=None,
                 clientExtensions=None):
        """
        Instantiate a StopLossOrderRequest.
        
        Parameters
        ----------
        tradeID : string
            the trade ID of an existing trade
        price : float
            the stop loss price
        """
        super(StopLossOrderRequest, self).__init__()
        
        self._data.update({"type": "STOP_LOSS"})
        self._data.update({"timeInForce": timeInForce})
        self._data.update({"tradeID": TradeID(tradeID).value})
        self._data.update({"price": PriceValue(price).value})
        
        if gtdTime and timeInForce == TimeInForce.GTD:
            self._data.update({"gtdTime": gtdTime})
        if clientExtensions:
            self._data.update({"clientExtensions": clientExtensions})
    
    @property
    def data(self):
        return dict({"order": super(StopLossOrderRequest, self).data})


